   679→fun try_stop_collateral_deleverage<MarketType, CollateralType>(id: &mut UID, reserves: &GenericCoinTypeStorage<Reserve<MarketType>>, collateral: TypeName) {
   680→    let total_deposit = reserves.load_by_type(collateral).cash_plus_borrows_minus_reserves().ceil();
   681→    let adl = dynamic_field::borrow_mut<ADLRegistryKey, AutoDeleverageRegistry>(id, ADLRegistryKey {});
