  1085→// sum of every collateral usd value for borrow, returns both the total collateral usd value and the collateral factor weighted usd value (price x amount x collateralFactor)
  1086→fun collaterals_usd_for_liquidation<MarketType>(
  1087→    emode_group: &EModeGroup,
  1088→    reserves: &GenericCoinTypeStorage<Reserve<MarketType>>,
  1089→
  1090→    obligation: &Obligation<MarketType>,
  1091→
  1092→    coin_decimals_registry: &CoinDecimalsRegistry,
  1093→    x_oracle: &XOracle,
  1094→    clock: &Clock,
  1095→): (Decimal, Decimal) {
  1096→    let mut total_weighted_usd = float::zero();
  1097→    let mut total_collateral_usd = float::zero();
  1098→
  1099→    let mut deposit_types = obligation.deposit_types();
  1100→    let oracle_base_token = emode_group.get_oracle_base_token();
  1101→
  1102→    while (!deposit_types.is_empty()) {
  1103→        let deposit_type = deposit_types.pop_back();
  1104→
  1105→        let collateral_config = emode_group.borrow_emode(deposit_type).collateral();
  1106→        // cannot be collateral, ignore
  1107→        if (!collateral_config.can_be_collateral()) { continue };
  1108→        
  1109→        let weight = collateral_config.liquidation_factor();
  1110→
  1111→        let ctoken_amount = obligation.ctoken_amount_by_coin<MarketType>(deposit_type);
  1112→        let reserve = reserves.load_by_type<Reserve<MarketType>>(deposit_type);
  1113→        let collateral_amount = reserve.exchange_rate().mul(float::from(ctoken_amount));
  1114→
  1115→        let coin_price = get_price(x_oracle, deposit_type, oracle_base_token, clock);
  1116→        let decimals = coin_decimals_registry.decimals(deposit_type);
  1117→        
  1118→        let collateral_value_usd = coin_value(coin_price, collateral_amount, decimals);
  1119→        let collateral_weighted_usd = collateral_value_usd.mul(weight);
  1120→
  1121→        total_collateral_usd = total_collateral_usd.add(collateral_value_usd);
  1122→        total_weighted_usd = total_weighted_usd.add(collateral_weighted_usd);
  1123→    };
  1124→
  1125→    (total_weighted_usd, total_collateral_usd)
  1126→}
